/* eslint-disable react/prop-types */
import React, { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Card,
  Stack,
  Button,
  Popover,
  MenuItem,
  Typography,
  IconButton,
  TablePagination,
} from '@mui/material';
import PersonAddAltIcon from '@mui/icons-material/PersonAddAlt';
// import { toast } from 'react-toastify';
import TanstackTableV8 from 'src/components/tanstackMUItable/tanstackTableV8';
import { axios } from '../../utils/axios';
import { replaceStarsInEmailAddress, replaceStarsInMobileNumber } from '../../utils/sensitive'
import { updateUrlParams } from '../../utils/urlUtilis';
// components
import Label from '../../components/label';
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import useResponsive from '../../hooks/useResponsive';

export default function UserPage() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)
  const navigate = useNavigate();
  const [open, setOpen] = useState(null);
  const [search, setsearch] = useState(queryParams.get('search') || '');
  const [opens, setOpens] = useState(false);
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [adminList, setAdminList] = React.useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const { settingsData, i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm');
  const [filters, setFilters] = useState({ firstname: '', phone: '' });
  const [isLoading, setIsLoading] = useState(true);
  const fetchData = async () => {
    setIsLoading(true);
    try {
      let url = `module/auth/admins?_page=${page}&_limit=${rowsPerPage}`;
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });

      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      const res = await axios.get(url);
      if (res.status === 200) {
        setAdminList(res.data.data.adminData);
        setTotalCount(res.data.data.totalCount ? res.data.data.totalCount : 0);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false); 
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleformdata = async (ids, list) => {
    navigate(`/dashboard/editadmin?id=${ids}`)
  };

  const handleCloseMenu = () => {
    setOpen(null);
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = adminList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleOpenModal = () => {
    const type = 'Admin';
    navigate('/dashboard/addprofile', { state: { types: type } });
  };

  const deleteModal = (ids) => {
    sessionStorage.setItem('rowAdminId', ids);
    setOpens(true);
  };

  const deleteAdmin = async () => {
    const ids = sessionStorage.getItem('rowAdminId');
    try {
      const res = await axios.delete(`module/auth/admin/${ids}`);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'info');
        setOpens(false);
        fetchData();
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };


  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    const newLimit = parseInt(event.target.value, 10);
    setRowsPerPage(newLimit);
    setPage(1);
  };

  const handleFilterByName = (event) => {
    const filterValue = event.target.value;
    setsearch(filterValue);
    queryParams.set('search', filterValue);
    window.history.pushState(null, '', `?${queryParams.toString()}`);
  };

  const ActionComponent = (cell) => {
    const value = cell.getValue();

    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    const handleformdata = async (ids, list) => {
      navigate(`/dashboard/editadmin?id=${ids}`)
    };

    const deleteModal = (ids) => {
      sessionStorage.setItem('rowAdminId', ids);
      setOpens(true);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => handleformdata(value)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>
          <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    );
  }



  const columns = [
    { 
      accessorKey: 'firstname', 
      id: 'firstname', 
      header: i18?.ACCOUNTSTITLE?.FULL_NAME || "Full Name", 
      showFilter: true,  
      cell: ({ row }) => `${row.original?.firstname} ${row.original?.lastname || ''}` 
    },
    {
      header: i18?.ACCOUNTSTITLE?.EMAIL_ID || "Email ID", 
      id: 'email',
      accessorKey: "email", 
      showFilter: true, 
      cell: ({ cell }) => <span>{replaceStarsInEmailAddress(cell.getValue(), settingsData, cell.getValue())}</span>,
    },
    {
      header: i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone Number",
      accessorKey: "phone", 
      id: 'phone', 
      showFilter: true, 
      cell: ({ cell }) => <span>{replaceStarsInMobileNumber(cell.getValue(), settingsData, cell.getValue())}</span>,
    },

    {
      header: i18?.ACCOUNTSTITLE?.STATUS || "Status",
      accessorKey: "isActive", // Field in your data representing the status
      id: 'isActive', // Unique ID for the column
      showFilter: false, // No filter for this column
      cell: ({ cell }) => {
        const value = cell.getValue(); // Retrieve the cell value (true/false)
        console.log("statuss", cell)
        return (
          <Label
            sx={{
              width: value ? '56px' : '66px',
              height: value ? '25px' : '27px',
              borderRadius: '60px',
              background: value ? '#E6FFFA' : '#FEF5E5', // Background based on status
              color: value ? '#0DAC6F' : '#FA886B', // Text color based on status
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            {value ? 'Active' : 'Inactive'} {/* Text based on status */}
          </Label>
        );
      },
    },

    {
      header: i18?.ACCOUNTSTITLE?.ACTION || "Action",
      accessorKey: "_id", id: 'action', showFilter: false,
      // cell: ({ cell: { value } })
      cell: ActionComponent
    }

  ];


  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1); // Reset to first page on filter change
  };

  return (
    <>
      <Helmet>
        <title> Admin | Admin panel </title>
      </Helmet>


      {isMobile && <Stack direction='row' alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
        <Typography variant="h4" gutterBottom>
          {i18?.ACCOUNTSTITLE?.ADMIN_LIST || "Admin List"}
        </Typography>

        <Button variant="contained" onClick={handleOpenModal} startIcon={<PersonAddAltIcon />}>
          {i18?.ACCOUNTSTITLE?.ADD_ADMIN || "Add Admin"}
        </Button>
      </Stack>}

      {!isMobile && <Stack direction='row' alignItems="center" justifyContent="space-between">
        <Stack direction={'row'} alignItems="center" >
          <Typography variant="h4" gutterBottom>
            {i18?.ACCOUNTSTITLE?.ADMIN_LIST || "Admin List"}
          </Typography>
        </Stack>

        <Stack direction='row' alignItems="center" >
          <UserListToolbar
            numSelected={selected.length}
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />
          <Button variant="contained" onClick={handleOpenModal} startIcon={<PersonAddAltIcon />}>
            {i18?.ACCOUNTSTITLE?.ADD_ADMIN || "Add Admin"}
          </Button>
        </Stack>

      </Stack>}

      <Card sx={{ padding: '0px 0px', margin: '0px 0px', overflowX: 'auto' }}>
        {isMobile && <UserListToolbar
          numSelected={selected.length}
          filterName={filterName}
          onFilterName={handleFilterByName}
          search={search}
          setsearch={setsearch}
        />}

        <Scrollbar>
          {/* <TanstackTable data={data} columns={columns} /> */}
          <TanstackTableV8
            data={adminList}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange} />
        </Scrollbar>

      </Card>

      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || 0}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />

      <Popover
        open={Boolean(open)}
        anchorEl={open}
        onClose={handleCloseMenu}
        anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
        PaperProps={{
          sx: {
            p: 1,
            width: 140,
            '& .MuiMenuItem-root': {
              px: 1,
              typography: 'body2',
              borderRadius: 0.75,
            },
          },
        }}
      >
        <MenuItem>
          <Iconify icon={'eva:edit-fill'} sx={{ mr: 2 }} />
          Edit
        </MenuItem>

        <MenuItem sx={{ color: 'error.main' }}>
          <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} />
          Delete
        </MenuItem>
      </Popover>

      <DeleteModal
        isDeleteOpen={opens}
        handleClose={() => setOpens(false)}
        handleDelete={deleteAdmin}
      />

    </>
  );
}
